def momentum_in(g, comp):
    tot = {}
    for v in comp:
        for k, c in g.ext.get(v, {}).items():
            tot[k] = tot.get(k, 0) + c
    return {k: c for k, c in tot.items() if c}

ft = box.two_forests()
