for rem, comp in ft:
    P2 = box.kin.square_external(momentum_in(box, comp))
    titles.append(xs(rem) + (":  0" if P2 == 0 else "  $%s$" % latex(P2)))
fig = draw_panels(box, [r for r, c in ft], titles=titles, momenta=False, ncols=3,
